// src/components/SEO.tsx
import React from "react";
import type { UserProfile } from "../interfaces";

interface Props {
  data: UserProfile;

  title?: string;
  description?: string;

  /**
   * i18next values — pass from graphql data when used in Gatsby Head API
   */
  language?: string;
  languages?: readonly string[];
  defaultLanguage?: string;
  originalPath?: string;

  /**
   * Optional overrides for canonical and social
   */
  pathname?: string;
  canonical?: string;
  image?: string;
  noindex?: boolean;

  /**
   * Schema overrides
   */
  schemaType?: "LocalBusiness" | "ProfessionalService" | "Organization";
  schemaName?: string;
  includeLocalBusinessDetails?: boolean;
  /** Schema.org type for the current page — one per route in this site */
  pageSchemaType?:
    | "WebPage"      // index, retail, 404
    | "AboutPage"    // about
    | "ContactPage"  // contact
    | "Service"      // industry
    | "CollectionPage"; // products
  pageSchemaName?: string;

  /**
   * Add extra JSON-LD schemas (e.g., FAQPage for blog posts)
   */
  additionalSchemas?: object | object[];
}

const DEFAULT_OG_IMAGE = "https://reefcleaningcompany.com/logo.png";

function stripTrailingSlash(url: string) {
  return url.replace(/\/+$/, "");
}

function ensureLeadingSlash(path: string) {
  if (!path) return "/";
  return path.startsWith("/") ? path : `/${path}`;
}

function stripQueryAndHash(path: string) {
  return path.split("?")[0].split("#")[0];
}

function ensureTrailingSlash(path: string) {
  if (!path) return "/";
  return path.endsWith("/") ? path : `${path}/`;
}

function isAbsoluteUrl(url?: string) {
  return !!url && /^https?:\/\//i.test(url);
}

function hasLanguagePrefix(path: string, langs: readonly string[]) {
  return langs.some((lng) => path === `/${lng}/` || path.startsWith(`/${lng}/`));
}

function localizePath(
  path: string,
  language: string,
  defaultLanguage: string,
  langs: readonly string[]
) {
  const normalized = ensureTrailingSlash(
    stripQueryAndHash(ensureLeadingSlash(path))
  );

  // If the caller already passed a localized pathname (/en/..., /es/...), keep it.
  if (hasLanguagePrefix(normalized, langs)) {
    return normalized;
  }

  if (!language || language === defaultLanguage) {
    return normalized;
  }

  return normalized === "/"
    ? `/${language}/`
    : ensureTrailingSlash(`/${language}${normalized}`);
}

const SEO: React.FC<Props> = ({
  data,
  title,
  description,
  language = "en",
  languages = ["en"],
  defaultLanguage = "en",
  originalPath = "/",
  pathname,
  canonical,
  image,
  noindex,
  schemaType = "LocalBusiness",
  schemaName,
  includeLocalBusinessDetails = false,
  pageSchemaType = "WebPage",
  pageSchemaName,
  additionalSchemas,
}) => {
  const resolvedTitle = title ?? "";
  const resolvedDescription = description ?? "";

  const siteUrl = stripTrailingSlash((data?.url || "").trim());

  const baseOriginalPath = ensureTrailingSlash(
    stripQueryAndHash(ensureLeadingSlash(originalPath || "/"))
  );

  const autoLocalizedPath =
    language === defaultLanguage
      ? baseOriginalPath
      : ensureTrailingSlash(`/${language}${baseOriginalPath}`);

  const localizedPathname = pathname
    ? localizePath(pathname, language, defaultLanguage, languages || [])
    : undefined;

  const finalPath = localizedPathname ?? autoLocalizedPath;

  const resolvedCanonical =
    canonical ?? (siteUrl ? `${siteUrl}${finalPath}` : undefined);

  const ogImage = isAbsoluteUrl(image)
    ? image
    : image && siteUrl
      ? `${siteUrl}${ensureLeadingSlash(image)}`
      : isAbsoluteUrl(data?.logoUrl)
        ? data.logoUrl
        : DEFAULT_OG_IMAGE;

  const hrefLangLinks =
    siteUrl && languages?.length
      ? languages.map((lng) => {
          const hrefPath =
            lng === defaultLanguage
              ? baseOriginalPath
              : ensureTrailingSlash(`/${lng}${baseOriginalPath}`);

          return (
            <link
              key={lng}
              rel="alternate"
              hrefLang={lng}
              href={`${siteUrl}${hrefPath}`}
            />
          );
        })
      : null;

  const xDefaultHref =
    siteUrl && defaultLanguage ? `${siteUrl}${baseOriginalPath}` : undefined;

  const entityUrl = siteUrl || resolvedCanonical;
  const entityId = entityUrl ? `${entityUrl}/#entity` : undefined;
  const websiteId = siteUrl ? `${siteUrl}/#website` : undefined;

  const entitySchema = {
    "@context": "https://schema.org",
    "@type": schemaType,
    ...(entityId ? { "@id": entityId } : {}),
    name: schemaName || data.name,
    image: ogImage,
    address: {
      "@type": "PostalAddress",
      streetAddress: data.address,
      addressLocality: data.city,
      addressRegion: data.province,
      postalCode: data.postalCode,
      ...(data.country ? { addressCountry: data.country } : { addressCountry: "US" }),
    },
    url: entityUrl,
    telephone: data.phone,
    sameAs: [data.instagram, data.facebook].filter(Boolean),
    ...(includeLocalBusinessDetails && schemaType !== "Organization"
      ? {
          geo: {
            "@type": "GeoCoordinates",
            latitude: data.latitude,
            longitude: data.longitude,
          },
          openingHours: data.openingHours,
        }
      : {}),
    ...(description ? { description } : {}),
  };

  const pageSchema = resolvedCanonical
    ? {
        "@context": "https://schema.org",
        "@type": pageSchemaType,
        "@id": `${resolvedCanonical}#webpage`,
        name: pageSchemaName || resolvedTitle,
        url: resolvedCanonical,
        ...(resolvedDescription ? { description: resolvedDescription } : {}),
        ...(language ? { inLanguage: language } : {}),
        ...(ogImage
          ? {
              primaryImageOfPage: {
                "@type": "ImageObject",
                url: ogImage,
              },
            }
          : {}),
        ...(websiteId
          ? {
              isPartOf: {
                "@type": "WebSite",
                "@id": websiteId,
                url: siteUrl,
                name: data.name,
              },
            }
          : {}),
        ...(entityId
          ? pageSchemaType === "Service"
            ? {
                provider: {
                  "@id": entityId,
                },
              }
            : {
                about: {
                  "@id": entityId,
                },
              }
          : {}),
      }
    : undefined;

  const extras = Array.isArray(additionalSchemas)
    ? additionalSchemas
    : additionalSchemas
      ? [additionalSchemas]
      : [];


      
  return (
    <>
      <html lang={language} />
      <title>{resolvedTitle}</title>
      <meta name="description" content={resolvedDescription} />

      {/* Canonical */}
      {resolvedCanonical ? <link rel="canonical" href={resolvedCanonical} /> : null}

      {/* hreflang alternates */}
      {hrefLangLinks}
      {xDefaultHref ? (
        <link rel="alternate" hrefLang="x-default" href={xDefaultHref} />
      ) : null}

      {/* Robots */}
      {noindex ? <meta name="robots" content="noindex, nofollow" /> : null}

      {/* Open Graph */}
      <meta property="og:type" content="website" />
      <meta property="og:title" content={resolvedTitle} />
      <meta property="og:description" content={resolvedDescription} />
      {resolvedCanonical ? <meta property="og:url" content={resolvedCanonical} /> : null}
      {ogImage ? <meta property="og:image" content={ogImage} /> : null}

      {/* Twitter */}
      <meta name="twitter:card" content="summary_large_image" />
      <meta name="twitter:title" content={resolvedTitle} />
      <meta name="twitter:description" content={resolvedDescription} />
      {ogImage ? <meta name="twitter:image" content={ogImage} /> : null}

      {/* Structured Data (base entity) */}
      <script type="application/ld+json">{JSON.stringify(entitySchema)}</script>

      {/* Structured Data (page) */}
      {pageSchema ? (
        <script type="application/ld+json">{JSON.stringify(pageSchema)}</script>
      ) : null}

      {/* Structured Data (extras) */}
      {extras.map((schema, idx) => (
        <script key={idx} type="application/ld+json">
          {JSON.stringify(schema)}
        </script>
      ))}
    </>
  );
};

export default SEO;