import React, { useState } from "react";
import { useTranslation, Link } from "gatsby-plugin-react-i18next";
import menuData from "../data/data.json";
import Icon from "../components/icon";
import { NavigationProps } from "../interfaces";

const Navigation: React.FC<NavigationProps> = ({
  iconAndTextColor,
}: NavigationProps) => {
  const { t } = useTranslation();
  const [isOpen, setIsOpen] = useState(false);
  const menuItems = menuData.menu;

  // Split menu items into two halves for left and right alignment
  const half = Math.ceil(menuItems.length / 2);
  const leftItems = menuItems.slice(0, half);
  const rightItems = menuItems.slice(half);
  const [moved, setMoved] = useState(false);

  const toggleMenu = () => {
    setMoved(!moved);
    setIsOpen(!isOpen);
  };

  return (
    <nav className="fixed h-[3.75rem] w-full px-0 text-Tofu z-50">
      <div className="flex justify-between items-center w-full sm:px-[3.75rem] h-full bg-black/20 backdrop-blur-xl">
        {/* Desktop Menu */}
        <div className="hidden md:flex justify-end">
          <ul className="flex space-x-6  min-w-full">
            {leftItems.map((item, index) => (
              <li key={index}>
                <a
                  href={`/${item}`}
                  className={`relative text-${iconAndTextColor} after:content-[''] after:absolute after:left-0 after:bottom-[-2px] after:w-full after:h-[2px] after:bg-current after:scale-x-0 after:transition-transform after:origin-left hover:after:scale-x-100`}
                >
                  {t(`menu.${item}`)}
                </a>
              </li>
            ))}
          </ul>
        </div>

        {/* Centered Logo */}
        <a href="/">
          <Icon className={`fill-${iconAndTextColor} w-8 h-8 ml-4 sm:ml-0`} />
        </a>

        <div className="hidden md:flex justify-start">
          <ul className="flex space-x-6">
            {rightItems.map((item, index) => (
              <li key={index}>
                <a
                  href={`/${item}`}
                  className={`relative text-${iconAndTextColor} after:content-[''] after:absolute after:left-0 after:bottom-[-2px] after:w-full after:h-[2px] after:bg-current after:scale-x-0 after:transition-transform after:origin-left hover:after:scale-x-100`}
                >
                  {t(`menu.${item}`)}
                </a>
              </li>
            ))}
          </ul>
        </div>

        {/* Mobile Button */}
        <button onClick={toggleMenu} className="sm:hidden mr-4">
          {isOpen ? <img src="../close.svg" /> : <img src="../menu.svg" />}
        </button>
      </div>

      {/* Mobile Menu */}
      <div
        className={`transition-transform top-[-285px] duration-700 ease-in-out transform z-[-1] absolute w-full ${
          moved ? "translate-y-[344px]" : "translate-y-0"
        }`}
      >
        <ul className="{`absolute z-40 left-0 w-full bg-black/10 !backdrop-blur-md md:hidden shadow-lg`}">
          {menuItems
            .filter((item) => item !== "_")
            .map((item, index) => (
              <li
                key={index}
                className={`p-4 ${
                  index < menuItems.length - 1 ? "border-b border-white/20" : ""
                }`}
              >
                <a
                  href={`/${item}`}
                  className={`text-${iconAndTextColor} block`}
                >
                  {t(`menu.${item}`)}
                </a>
              </li>
            ))}
        </ul>
      </div>
    </nav>
  );
};

export default Navigation;
